    // 4 & 5. AnidbCollection & BookCollection helpers
    // -------------------------------------------------------------------------

    #[allow(clippy::too_many_arguments)]
    #[inline]
    unsafe fn collection_resolve_meta(
        has_total: u32,
        total_val: i64,
        has_per_page: u32,
        per_page_val: i64,
        has_current_page: u32,
        current_page_val: i64,
        has_last_page: u32,
        last_page_val: i64,
        collection_count: i64,
        out_meta: *mut i64,
        meta_cap: usize,
    ) -> isize {
        if !valid_i64_out(out_meta, meta_cap, 0) || collection_count < 0 {
            return DECLINE;
        }
        if meta_cap < 4 {
            return -4;
        }
        let resolved = [
            if has_total != 0 {
                total_val
            } else {
                collection_count
            },
            if has_per_page != 0 {
                per_page_val
            } else {
                collection_count
            },
            if has_current_page != 0 {
                current_page_val
            } else {
                1
            },
            if has_last_page != 0 {
                last_page_val
            } else {
                1
            },
        ];
        let slice_out = unsafe { slice::from_raw_parts_mut(out_meta, 4) };
        slice_out.copy_from_slice(&resolved);
        4
    }

    #[allow(clippy::too_many_arguments)]
    #[inline]
    unsafe fn collection_build_envelope(
        has_total: u32,
        total_val: i64,
        has_per_page: u32,
        per_page_val: i64,
        has_current_page: u32,
        current_page_val: i64,
        has_last_page: u32,
        last_page_val: i64,
        collection_count: i64,
        has_first: u32,
        first_ptr: *const u8,
        first_len: usize,
        has_last: u32,
        last_ptr: *const u8,
        last_len: usize,
        has_prev: u32,
        prev_ptr: *const u8,
        prev_len: usize,
        has_next: u32,
        next_ptr: *const u8,
        next_len: usize,
        out_buf: *mut u8,
        out_cap: usize,
    ) -> isize {
        if !valid_out_cap(out_buf, out_cap) || collection_count < 0 {
            return DECLINE;
        }
        let (Some(first_url), Some(last_url), Some(prev_url), Some(next_url)) = (
            unsafe { input(first_ptr, first_len) },
            unsafe { input(last_ptr, last_len) },
            unsafe { input(prev_ptr, prev_len) },
            unsafe { input(next_ptr, next_len) },
        ) else {
            return DECLINE;
        };

        let total = if has_total != 0 {
            total_val
        } else {
            collection_count
        };
        let per_page = if has_per_page != 0 {
            per_page_val
        } else {
            collection_count
        };
        let current_page = if has_current_page != 0 {
            current_page_val
        } else {
            1
        };
        let last_page = if has_last_page != 0 {
            last_page_val
        } else {
            1
        };

        let mut w = PhpSerWriter::new();
        w.arr_open(2);
        w.key(b"meta");
        w.arr_open(4);
        w.key(b"total");
        w.int(total);
        w.key(b"per_page");
        w.int(per_page);
        w.key(b"current_page");
        w.int(current_page);
        w.key(b"last_page");
        w.int(last_page);
        w.arr_close();

        w.key(b"links");
        w.arr_open(4);
        w.key(b"first");
        if has_first != 0 {
            w.str(first_url);
        } else {
            w.null();
        }
        w.key(b"last");
        if has_last != 0 {
            w.str(last_url);
        } else {
            w.null();
        }
        w.key(b"prev");
        if has_prev != 0 {
            w.str(prev_url);
        } else {
            w.null();
        }
        w.key(b"next");
        if has_next != 0 {
            w.str(next_url);
        } else {
            w.null();
        }
        w.arr_close();
        w.arr_close();

        unsafe { write_bytes(out_buf, out_cap, &w.buf) }
    }

    /// Resolves the 4 pagination metadata integers (`[total, per_page, current_page, last_page]`)
    /// for `AnidbCollection` into `out_meta[..4]`.
    #[allow(clippy::too_many_arguments)]
    #[unsafe(no_mangle)]
